<template><><header class="topbar"><button class="icon-btn menu-btn" type="button" aria-label="切换侧边栏" @click="sidebarOpen=!sidebarOpen">☰</button><router-link class="brand" to="/" aria-label="首页">海角<span class="brand-x">AV</span></router-link><div class="search-wrap"><input v-model="keyword" type="search" placeholder="搜索视频" aria-label="搜索视频" @keyup.enter="search"><button class="search-btn" type="button" aria-label="搜索" @click="search">⌕</button></div><div class="top-actions"><router-link class="action" to="/history">历史</router-link></div></header><aside class="sidebar" :class="{open:sidebarOpen}"><nav aria-label="侧边导航"><router-link class="nav-item" to="/" @click="closeMobile"><span class="nav-icon">⌂</span><span class="nav-label">首页</span></router-link><router-link class="nav-item" to="/latest" @click="closeMobile"><span class="nav-icon">◷</span><span class="nav-label">最新</span></router-link><router-link class="nav-item" to="/popular" @click="closeMobile"><span class="nav-icon">★</span><span class="nav-label">热门</span></router-link><router-link class="nav-item" to="/trending" @click="closeMobile"><span class="nav-icon">↗</span><span class="nav-label">趋势</span></router-link><router-link class="nav-item" to="/categories" @click="closeMobile"><span class="nav-icon">▦</span><span class="nav-label">分类</span></router-link><router-link class="nav-item" to="/history" @click="closeMobile"><span class="nav-icon">▤</span><span class="nav-label">观看记录</span></router-link></nav></aside><div v-if="sidebarOpen" class="sidebar-backdrop" @click="sidebarOpen=false"></div></></template><script setup>import{ref}from'vue';import{useRouter}from'vue-router';const router=useRouter(),keyword=ref(''),sidebarOpen=ref(false);function closeMobile(){sidebarOpen.value=false}function search(){const wd=keyword.value.trim().slice(0,100);if(!wd)return;router.push({path:'/search',query:{wd}});closeMobile()}</script>